export { getBigNumberSize } from 'pages/components/ValueCreation/utils/getBigNumberSize';

export { getSustainableGrowthOverviewTitle } from './getSectionTitle';

export interface SkeletonProps {
  height: string;
  width: string;
  length: number;
  hasContainer: boolean;
}

export const getSustainableGrowthOverviewCardSkeletonProps = (
  isDesktopXLarge: boolean,
  isDesktopLarge: boolean,
  isExportPage = false,
): SkeletonProps => {
  if (isExportPage) {
    return {
      height: '568px',
      width: '312px',
      length: 5,
      hasContainer: false,
    };
  }
  if (isDesktopXLarge) {
    return {
      height: '484px',
      width: '264px',
      length: 5,
      hasContainer: false,
    };
  }
  if (isDesktopLarge) {
    return {
      height: '474px',
      width: '228px',
      length: 5,
      hasContainer: false,
    };
  }
  return {
    height: '468px',
    width: '198px',
    length: 5,
    hasContainer: false,
  };
};

export const getGrowthLeverCardSkeletonProps = (
  isDesktopXLarge: boolean,
  isDesktopLarge: boolean,
  isExportPage = false,
): SkeletonProps => {
  if (isExportPage) {
    return {
      height: '96px',
      width: '395px',
      length: 4,
      hasContainer: false,
    };
  }
  if (isDesktopXLarge) {
    return {
      height: '90px',
      width: '340px',
      length: 4,
      hasContainer: false,
    };
  }
  if (isDesktopLarge) {
    return {
      height: '90px',
      width: '290px',
      length: 4,
      hasContainer: false,
    };
  }
  return {
    height: '90px',
    width: '250px',
    length: 4,
    hasContainer: false,
  };
};

export const getStrategyDriverCardSkeletonProps = (
  isDesktopXLarge: boolean,
  isDesktopLarge: boolean,
  isExportPage = false,
): SkeletonProps => {
  if (isExportPage) {
    return {
      height: '90px',
      width: '512px',
      length: 3,
      hasContainer: false,
    };
  }
  if (isDesktopXLarge) {
    return {
      height: '78px',
      width: '452px',
      length: 3,
      hasContainer: false,
    };
  }
  if (isDesktopLarge) {
    return {
      height: '75px',
      width: '392px',
      length: 3,
      hasContainer: false,
    };
  }
  return {
    height: '75px',
    width: '338px',
    length: 3,
    hasContainer: false,
  };
};
